import * as Cloudflare from "@alchemy.run/cloudflare";
import { fileURLToPath } from "node:url";

/**
 * The D1 database for the Worker API.
 *
 * `migrations` points at the SQL files generated by drizzle-kit. Alchemy
 * applies pending migrations to D1 during every deploy. The path is anchored
 * to this file because the stack runs from the repository root.
 */
export const Database = Cloudflare.D1.Database("Database", {
  migrations: fileURLToPath(new URL("../drizzle/", import.meta.url)),
});
